                    )
                    .border(
                        width = 2.dp,
                        color = Color.White.copy(alpha = 0.3f + progress * 0.5f),
                        shape = CircleShape
                    )
            )
        }

        Box(
            modifier = Modifier
                .size(if (isRecording.value) 72.dp else 80.dp)
                .background(
                    if (isRecording.value) Color.Red else Color.White,
                    CircleShape
                )
                .pointerInput(Unit) {
                    val thresholdPx = LockDragThreshold.toPx()
                    awaitPointerEventScope {
                        while (true) {
                            val down = awaitFirstDown()

                            if (isRecording.value) {
                                val up = waitForUpOrCancellation()
                                if (up != null) {
                                    onToggleVideo()
                                }
                                continue
                            }

                            val longPressTimeout = viewConfiguration.longPressTimeoutMillis
                            val upChange = withTimeoutOrNull(longPressTimeout) {
                                while (true) {
                                    val event = awaitPointerEvent()
                                    val pointer = event.changes.firstOrNull() ?: break
                                    if (pointer.pressed == false) return@withTimeoutOrNull pointer
                                    pointer.consume()
                                }
                                null
                            }

                            if (upChange == null) {
                                if (!isRecording.value) {
                                    onToggleVideo()
                                }

                                while (true) {
                                    val event = awaitPointerEvent()
                                    val pointer = event.changes.firstOrNull()

                                    if (pointer == null || pointer.pressed == false) {
                                        if (!isRecordingLocked.value) {
                                            onToggleVideo()
                                        }
                                        lockDragOffset.value = 0f
                                        break
                                    } else {
                                        val yOffset = down.position.y - pointer.position.y
                                        if (!isRecordingLocked.value) {
                                            lockDragOffset.value = yOffset.coerceAtLeast(0f)
                                            if (lockDragOffset.value >= thresholdPx) {
                                                isRecordingLocked.value = true
                                                lockDragOffset.value = 0f
                                            }
                                        }
                                        pointer.consume()
                                    }
                                }
                            } else {
                                if (!isRecording.value) {
                                    onTakePhoto()
                                }
                            }
                        }
                    }
                }
        ) {
            if (isRecordingLocked.value) {
                Icon(
                    Icons.Default.Lock,
                    contentDescription = "Locked",
                    tint = Color.White,
                    modifier = Modifier
                        .size(32.dp)
